import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Auctions","description":"","frontmatter":{"pageId":"players/auctions","contentRevision":1},"headers":[],"relativePath":"en/players/auctions.md","filePath":"en/players/auctions.md"}'),s={name:"en/players/auctions.md"};function r(o,e,l,d,c,u){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="auctions" tabindex="-1">Auctions <a class="header-anchor" href="#auctions" aria-label="Permalink to &quot;Auctions&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Select items, a starting price and a duration. Auctions accept items, not pawns. The seller can cancel before the first bid. Bidding uses the wallet: the entire current bid is reserved and a displaced bidder is refunded.</p><p>At settlement the winner receives a parcel and the seller receives proceeds minus any fee. A bid in the last 30 seconds extends the end by 30 seconds, up to 5 minutes total. Refresh the list to see the current deadline.</p><p>The seller need not be online for settlement. A freeze defers settlement until permitted; an administrator can cancel a problematic auction.</p><h3 id="bid-or-buy-out" tabindex="-1">Bid or buy out <a class="header-anchor" href="#bid-or-buy-out" aria-label="Permalink to &quot;Bid or buy out&quot;">​</a></h3><p>Open the auctions tab in the economy window. To sell, choose items, starting price, duration in hours and an optional buyout price (0 disables buyout). Confirm posting and wait for the save/escrow transfer. To buy, refresh the list and inspect the goods and current price: a normal bid reserves wallet funds until settlement. <strong>Buyout</strong> at the seller&#39;s configured price ends bidding immediately; check the winner&#39;s mailbox and remaining balance. If funds are insufficient, deposit first instead of sending the seller a separate transfer outside the auction.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>The API allows 60 seconds–30 days; the game UI allows 1–720 hours. Reset/archive cancels related escrow. Sellers cannot rely on manual cancellation after bidding starts.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./economy">Wallet, mail and market</a></li><li><a href="./../admins/gameplay-policy">Server gameplay policy</a></li></ul>',12)])])}const m=a(s,[["render",r]]);export{p as __pageData,m as default};
